import { Injectable } from '@angular/core';
import { Observable, of, BehaviorSubject, delay } from 'rxjs';
import { MailMessage, MailDraft, MailQuery, MailAddress } from '../models/mail.model';
import { MailFolder } from '../models/folder.model';
import { MOCK_MESSAGES } from '../mock/mock-mail-data';
import { MOCK_FOLDERS } from '../mock/mock-folders';

@Injectable({ providedIn: 'root' })
export class MailService {
  private messages: MailMessage[] = [...MOCK_MESSAGES];
  private folders: MailFolder[] = [...MOCK_FOLDERS];
  private nextId = 100;

  private messagesSubject = new BehaviorSubject<MailMessage[]>(this.messages);
  private foldersSubject = new BehaviorSubject<MailFolder[]>(this.folders);

  messages$ = this.messagesSubject.asObservable();
  folders$ = this.foldersSubject.asObservable();

  listMessages(query?: MailQuery): Observable<MailMessage[]> {
    let filtered = [...this.messages];

    if (query) {
      if (query.folderId) {
        if (query.folderId === 'starred') {
          filtered = filtered.filter(m => m.isStarred);
        } else if (query.folderId === 'bookmarked') {
          filtered = filtered.filter(m => m.isBookmarked);
        } else {
          filtered = filtered.filter(m => m.folderId === query.folderId);
        }
      }
      if (query.labelId) {
        filtered = filtered.filter(m => m.labels.includes(query.labelId!));
      }
      if (query.search) {
        const term = query.search.toLowerCase();
        /* ユーザー指示 2026-04-23: 件名・本文・差出人に加え、宛先 (to/cc) も
           検索対象に含める */
        filtered = filtered.filter(m =>
          m.subject.toLowerCase().includes(term) ||
          m.body.toLowerCase().includes(term) ||
          m.from.name.toLowerCase().includes(term) ||
          m.from.email.toLowerCase().includes(term) ||
          m.snippet.toLowerCase().includes(term) ||
          (m.to || []).some(a =>
            a.name.toLowerCase().includes(term) ||
            a.email.toLowerCase().includes(term)
          ) ||
          (m.cc || []).some(a =>
            a.name.toLowerCase().includes(term) ||
            a.email.toLowerCase().includes(term)
          )
        );
      }
      if (query.isRead !== undefined) {
        filtered = filtered.filter(m => m.isRead === query.isRead);
      }
      if (query.isStarred !== undefined) {
        filtered = filtered.filter(m => m.isStarred === query.isStarred);
      }
      if (query.isBookmarked !== undefined) {
        filtered = filtered.filter(m => m.isBookmarked === query.isBookmarked);
      }
      if (query.hasAttachments !== undefined) {
        filtered = filtered.filter(m => m.hasAttachments === query.hasAttachments);
      }
      if (query.from) {
        const fromTerm = query.from.toLowerCase();
        filtered = filtered.filter(m =>
          m.from.name.toLowerCase().includes(fromTerm) ||
          m.from.email.toLowerCase().includes(fromTerm)
        );
      }
      if (query.dateFrom) {
        filtered = filtered.filter(m => m.date >= query.dateFrom!);
      }
      if (query.dateTo) {
        filtered = filtered.filter(m => m.date <= query.dateTo!);
      }
    }

    filtered.sort((a, b) => b.date.getTime() - a.date.getTime());
    return of(filtered);
  }

  getMessage(id: string): Observable<MailMessage | undefined> {
    return of(this.messages.find(m => m.id === id));
  }

  getThreadMessages(threadId: string): Observable<MailMessage[]> {
    const threadMsgs = this.messages
      .filter(m => m.threadId === threadId)
      .sort((a, b) => a.date.getTime() - b.date.getTime());
    return of(threadMsgs);
  }

  sendMessage(draft: MailDraft): Observable<MailMessage> {
    const newMsg: MailMessage = {
      id: `msg-${this.nextId++}`,
      from: { name: '石崎太一', email: 'ishizaki.taichi@example.co.jp' },
      to: draft.to,
      cc: draft.cc,
      bcc: draft.bcc,
      subject: draft.subject,
      body: draft.body,
      bodyHtml: draft.bodyHtml,
      snippet: draft.body.substring(0, 80),
      date: new Date(),
      isRead: true,
      isStarred: false,
      isBookmarked: false,
      folderId: 'sent',
      labels: [],
      attachments: draft.attachments || [],
      threadId: draft.threadId || `thread-${this.nextId}`,
      inReplyTo: draft.inReplyTo,
      hasAttachments: (draft.attachments?.length || 0) > 0,
    };
    this.messages = [newMsg, ...this.messages];
    this.messagesSubject.next(this.messages);
    return of(newMsg);
  }

  replyMessage(messageId: string, body: string, bodyHtml: string, replyAll: boolean = false): Observable<MailMessage> {
    const original = this.messages.find(m => m.id === messageId);
    if (!original) {
      throw new Error('Message not found');
    }

    const to: MailAddress[] = [original.from];
    let cc: MailAddress[] | undefined;
    if (replyAll) {
      const myEmail = 'ishizaki.taichi@example.co.jp';
      const additionalTo = original.to.filter(a => a.email !== myEmail);
      to.push(...additionalTo);
      if (original.cc) {
        cc = original.cc.filter(a => a.email !== myEmail);
      }
    }

    const draft: MailDraft = {
      to,
      cc,
      subject: original.subject.startsWith('Re: ') ? original.subject : `Re: ${original.subject}`,
      body,
      bodyHtml,
      inReplyTo: messageId,
      threadId: original.threadId,
      mode: replyAll ? 'replyAll' : 'reply',
    };
    return this.sendMessage(draft);
  }

  forwardMessage(messageId: string, to: MailAddress[], body: string, bodyHtml: string): Observable<MailMessage> {
    const original = this.messages.find(m => m.id === messageId);
    if (!original) {
      throw new Error('Message not found');
    }

    const draft: MailDraft = {
      to,
      subject: original.subject.startsWith('Fwd: ') ? original.subject : `Fwd: ${original.subject}`,
      body,
      bodyHtml,
      attachments: original.attachments,
      threadId: original.threadId,
      mode: 'forward',
    };
    return this.sendMessage(draft);
  }

  moveToFolder(messageIds: string[], folderId: string): Observable<void> {
    this.messages = this.messages.map(m => {
      if (messageIds.includes(m.id)) {
        return { ...m, folderId };
      }
      return m;
    });
    this.messagesSubject.next(this.messages);
    this.updateFolderCounts();
    return of(void 0);
  }

  toggleStar(messageId: string): Observable<MailMessage> {
    let updated: MailMessage | undefined;
    this.messages = this.messages.map(m => {
      if (m.id === messageId) {
        updated = { ...m, isStarred: !m.isStarred };
        return updated;
      }
      return m;
    });
    this.messagesSubject.next(this.messages);
    this.updateFolderCounts();
    return of(updated!);
  }

  toggleBookmark(messageId: string): Observable<MailMessage> {
    let updated: MailMessage | undefined;
    this.messages = this.messages.map(m => {
      if (m.id === messageId) {
        updated = { ...m, isBookmarked: !m.isBookmarked };
        return updated;
      }
      return m;
    });
    this.messagesSubject.next(this.messages);
    this.updateFolderCounts();
    return of(updated!);
  }

  markAsRead(messageIds: string[], isRead: boolean = true): Observable<void> {
    this.messages = this.messages.map(m => {
      if (messageIds.includes(m.id)) {
        return { ...m, isRead };
      }
      return m;
    });
    this.messagesSubject.next(this.messages);
    this.updateFolderCounts();
    return of(void 0);
  }

  deleteMessage(messageIds: string[]): Observable<void> {
    return this.moveToFolder(messageIds, 'trash');
  }

  listFolders(): Observable<MailFolder[]> {
    this.updateFolderCounts();
    return of(this.folders);
  }

  // Label management methods
  createLabel(name: string, color: string): Observable<MailFolder> {
    const id = 'label-' + name.toLowerCase().replace(/[^a-z0-9\u3000-\u9fff\uf900-\ufaff]/g, '-') + '-' + Date.now();
    const newLabel: MailFolder = {
      id,
      name,
      icon: 'label',
      type: 'label',
      unreadCount: 0,
      color,
    };
    this.folders = [...this.folders, newLabel];
    this.foldersSubject.next(this.folders);
    return of(newLabel);
  }

  deleteLabel(labelId: string): Observable<void> {
    this.folders = this.folders.filter(f => f.id !== labelId);
    this.messages = this.messages.map(m => {
      if (m.labels.includes(labelId)) {
        return { ...m, labels: m.labels.filter(l => l !== labelId) };
      }
      return m;
    });
    this.foldersSubject.next(this.folders);
    this.messagesSubject.next(this.messages);
    return of(void 0);
  }

  addLabelToMessage(messageId: string, labelId: string): Observable<MailMessage> {
    let updated: MailMessage | undefined;
    this.messages = this.messages.map(m => {
      if (m.id === messageId) {
        if (!m.labels.includes(labelId)) {
          updated = { ...m, labels: [...m.labels, labelId] };
          return updated;
        }
        updated = m;
      }
      return m;
    });
    this.messagesSubject.next(this.messages);
    this.updateFolderCounts();
    return of(updated!);
  }

  removeLabelFromMessage(messageId: string, labelId: string): Observable<MailMessage> {
    let updated: MailMessage | undefined;
    this.messages = this.messages.map(m => {
      if (m.id === messageId) {
        updated = { ...m, labels: m.labels.filter(l => l !== labelId) };
        return updated;
      }
      return m;
    });
    this.messagesSubject.next(this.messages);
    this.updateFolderCounts();
    return of(updated!);
  }

  getAvailableColors(): string[] {
    return [
      '#e53935', // red
      '#1e88e5', // blue
      '#ff9800', // orange
      '#43a047', // green
      '#8e24aa', // purple
      '#d81b60', // pink
      '#00897b', // teal
      '#6d4c41', // brown
    ];
  }

  searchMessages(term: string): Observable<MailMessage[]> {
    return this.listMessages({ search: term });
  }

  getContacts(): Observable<MailAddress[]> {
    const contacts: MailAddress[] = [
      { name: '田中太郎', email: 'tanaka.taro@example.co.jp' },
      { name: '佐藤花子', email: 'sato.hanako@example.co.jp' },
      { name: '山田一郎', email: 'yamada.ichiro@example.co.jp' },
      { name: '鈴木健二', email: 'suzuki.kenji@example.co.jp' },
      { name: '高橋美咲', email: 'takahashi.misaki@example.co.jp' },
      { name: '渡辺直人', email: 'watanabe.naoto@example.co.jp' },
      { name: '伊藤めぐみ', email: 'ito.megumi@example.co.jp' },
      { name: '中村大輔', email: 'nakamura.daisuke@example.co.jp' },
      { name: '小林由美子', email: 'kobayashi.yumiko@example.co.jp' },
      { name: '加藤正義', email: 'kato.masayoshi@example.co.jp' },
    ];
    return of(contacts);
  }

  private updateFolderCounts(): void {
    this.folders = this.folders.map(f => {
      if (f.id === 'starred') {
        return { ...f, unreadCount: this.messages.filter(m => m.isStarred && m.folderId !== 'trash').length };
      }
      if (f.id === 'bookmarked') {
        return { ...f, unreadCount: this.messages.filter(m => m.isBookmarked && m.folderId !== 'trash').length };
      }
      if (f.type === 'system') {
        const unread = this.messages.filter(m => m.folderId === f.id && !m.isRead).length;
        return { ...f, unreadCount: unread };
      }
      if (f.type === 'label') {
        const unread = this.messages.filter(m => m.labels.includes(f.id) && !m.isRead && m.folderId !== 'trash').length;
        return { ...f, unreadCount: unread };
      }
      return f;
    });
    this.foldersSubject.next(this.folders);
  }
}
